import Foundation

/// Atlas entries for the controls of Music's search, cards, track lists and detail pages.
enum AtlasMusicLists {
    private static func c(_ id: String, _ title: String, _ summary: String, _ path: [String]) -> AtlasEntry {
        .make(id, .control, title, summary, path: path, platforms: .mac)
    }

    static let all: [AtlasEntry] = [
        c("control.music.searchField", "Music search field", "Type to see suggestions: your words first, completions, then a few songs. Return searches, the arrows move through the list and Escape clears it.", ["Music", "Search"]),
        c("control.music.suggestSearch", "Search the typed words", "The first suggestion always searches exactly what you typed.", ["Music", "Search"]),
        c("control.music.suggestFill", "Put a suggestion in the search field", "The arrow beside a completion copies it into the field so you can keep typing.", ["Music", "Search"]),
        c("control.music.categoryTile", "Music category", "A mood or genre tile on the empty search page. It opens that category.", ["Music", "Search"]),
