        c("control.music.topResultPlay", "Play the top result", "Plays the best match for your search, whether it is a song, an artist, an album or a playlist.", ["Music", "Search"]),
        c("control.music.topResultRadio", "Start radio from the top result", "Starts a radio of similar songs from the best match for your search.", ["Music", "Search"]),
        c("control.music.cardPlay", "Play from a card", "The round play button on a cover appears when you point at it or tab to it.", ["Music", "Cards"]),
        c("control.music.showAll", "Show all in a shelf", "Opens every item of a shelf in one grid.", ["Music", "Shelves"]),
