        c("control.music.errorRetry", "Try a failed page again", "Shown on a page that could not load. Loads it again.", ["Music", "Pages"]),
        c("control.music.bannerRetry", "Try the missing results again", "Shown in the banner above results when only some of them could not be loaded. The results already shown stay.", ["Music", "Pages"]),
