        c("control.music.lyricsBrowse", "Scroll the lyrics yourself", "Dragging the lyrics pauses the automatic follow so you can read ahead. It resumes by itself after a moment.", ["Music", "Lyrics"]),
        c("control.music.lyricsEditWordEdge", "Drag the edge of a word in the lyrics editor", "Drag the start or end of a word on the timeline to change when it is sung.", ["Music", "Lyrics", "Editor"]),
