        c("control.music.artworkOnline", "Find pictures online", "Lets Music look up photos of people, film posters and album covers from Wikipedia, Wikidata, TMDB, IMDb, Deezer, Apple Music and JioSaavn when a song, album or person has no picture. Only names and titles are sent, never what you play, and a picture is used only when it is verified to be the right one. Off: only pictures the app already holds are shown.", ["Music", "Settings", "Plugins & Sources", "Metadata sources"]),
        c("control.music.subsonicUse", "Use my music server", "Turns your own Subsonic or Navidrome server on or off as a music source. Turn it on to use it.", ["Music", "Settings", "Plugins & Sources", "Your music server"]),
        c("control.music.subsonicAdd", "Add a music server", "Saves the address, user name and password of your own Subsonic or Navidrome server. You can add up to three. The password goes to the Keychain.", ["Music", "Settings", "Plugins & Sources", "Your music server"]),
        c("control.music.subsonicTest", "Test a music server", "Checks that the server answers and that the user name and password are right, and says so in plain words. Nothing is saved by testing.", ["Music", "Settings", "Plugins & Sources", "Your music server"]),
        c("control.music.subsonicRemove", "Remove a music server", "Takes the server and its saved password off this device. Nothing changes on the server.", ["Music", "Settings", "Plugins & Sources", "Your music server"]),
        c("control.music.subsonicOwnNetwork", "This is my own server on my network", "Tick this to use a music server at an address on your home or office network. Only the addresses you add are allowed.", ["Music", "Settings", "Plugins & Sources", "Your music server"]),
        c("control.music.subsonicConvert", "Convert audio on the music server", "Ask your server to convert songs to MP3, Opus or AAC, and to keep to a highest bit rate. Server decides plays the files as they are.", ["Music", "Settings", "Plugins & Sources", "Your music server"]),
        c("control.music.queueStopAfter", "Stop after this song", "Playback stops when the song that is playing now ends, and the next song waits instead of starting. Press it again to take it back. It is in the queue, above the list.", ["Music", "Queue"]),
        c("control.music.queueSaveAsPlaylist", "Save the queue as a playlist", "Opens Add to Playlist with every song in the queue, so you can make a new playlist from it or add the songs to one you have. It is in the queue, above the list.", ["Music", "Queue"]),
        c("control.music.queueUndo", "Undo a queue change", "Brings back songs you removed or cleared from the queue, or puts a moved song back. Also Command-Z in the queue, or the Undo button in the message.", ["Music", "Queue"]),
        c("control.music.queueRedo", "Redo a queue change", "Does the queue change you undid again. Also Shift-Command-Z in the queue.", ["Music", "Queue"]),
        c("control.music.outputDevice", "Choose the output device for Music", "Pick where Music plays on this Mac. If the device is unplugged Music uses the system output and goes back to it when it returns. Other apps are never affected.", ["Music", "Settings", "Playback", "Output device"]),
        c("control.music.libraryTabMenu", "Choose a library section", "On a narrow window the Library tabs become this menu. Pick Songs, Albums, Artists, Playlists, History or Local files.", ["Music", "Your Library"]),
        c("control.music.libraryDownloads", "Open Downloads", "Goes to the songs you saved for offline listening.", ["Music", "Your Library"]),
        c("control.music.libraryViewMode", "Choose how the library is shown", "Switch between grid, list, compact list and table. The choice is remembered for each tab.", ["Music", "Your Library"]),
        c("control.music.librarySort", "Sort the library tab", "Order the tab by recently added, recently played, A to Z, artist, album, release date or length. The sort is remembered for each tab.", ["Music", "Your Library"]),
        c("control.music.librarySortReverse", "Reverse the sort", "Flips the order of the current sort.", ["Music", "Your Library"]),
        c("control.music.libraryFilter", "Filter this tab", "Type to keep only the songs, albums, artists or playlists that match. The filter is remembered while you move around.", ["Music", "Your Library"]),
        c("control.music.libraryFilterClear", "Clear the filter text", "Removes the words typed in the filter field.", ["Music", "Your Library"]),
        c("control.music.librarySource", "Filter the library by source", "Show only what came from one source, such as local files or a connected service.", ["Music", "Your Library"]),
        c("control.music.libraryChip", "Remove an active filter", "Each chip names a filter or sort that is on. Click it to remove that one.", ["Music", "Your Library"]),
        c("control.music.libraryClearFilters", "Clear all filters", "Removes the filter text and the source filter at once.", ["Music", "Your Library"]),
        c("control.music.libraryPlay", "Play these songs", "Plays the songs shown, in the order shown.", ["Music", "Your Library"]),
        c("control.music.libraryShuffle", "Shuffle these songs", "Plays the songs shown in a random order.", ["Music", "Your Library"]),
        c("control.music.librarySongActions", "More actions for these songs", "Add the songs to the queue, play them next, or download a short list.", ["Music", "Your Library"]),
        c("control.music.libraryAddQueue", "Add these songs to the queue", "Adds every song shown to the end of the queue.", ["Music", "Your Library"]),
        c("control.music.libraryPlayNext", "Play these songs next", "Puts every song shown right after the current one.", ["Music", "Your Library"]),
        c("control.music.libraryDownload", "Download these songs", "Saves the songs shown for offline listening. Offered for lists of 100 songs or fewer.", ["Music", "Your Library"]),
        c("control.music.librarySelect", "Select songs", "Pick several songs to add to a playlist, queue or remove them.", ["Music", "Your Library"]),
        c("control.music.libraryMore", "More library actions", "Import playlists, export or import a backup, create a playlist, or open the Never Play list.", ["Music", "Your Library"]),
        c("control.music.libraryNewPlaylist", "New playlist", "Creates an empty playlist in your library.", ["Music", "Your Library"]),
        c("control.music.libraryRow", "Library row", "One song, album, artist or playlist. Click to play or open it; right-click for more.", ["Music", "Your Library"]),
        c("control.music.libraryShowMore", "Show more history", "Adds the next page of plays to the history list.", ["Music", "Your Library"]),
        c("control.music.libraryEmptyAction", "Fill an empty library", "On an empty tab, each button opens a real way to add music: Search, Explore, Import, Settings or a new playlist.", ["Music", "Your Library"]),
        c("control.music.libraryEntityPlay", "Play this item", "Plays the album, artist or playlist.", ["Music", "Your Library"]),
        c("control.music.libraryEntityShuffle", "Shuffle this item", "Plays the album, artist or playlist in a random order.", ["Music", "Your Library"]),
        c("control.music.libraryEntityQueue", "Add this item to the queue", "Adds its songs to the end of the queue.", ["Music", "Your Library"]),
